\begin{align*}S - 0x &= 1 + 2x + 3x^2 + 4x^3 + \cdots \\ Sx - 0x &= 0x + 2x^2 + 3x^3 + 4x^4 + \cdots \\ -[S - 0x] + [Sx - 0x] &= 1 + x^2 + 2x^3 + 3x^4 + \cdots \\ x(S - Sx) &= 1 + x^2 + 2x^3 + 3x^4 + \cdots \\ xS(1-x) &= \dfrac{1}{1-x} + x^2 + 2x^3 + 3x^4 + \cdots \\ xS(1-x) &= 1 - x + x^2 + 2x^3 + 3x^4 + \cdots \\ xS(1-x) &= \dfrac{1}{1-x}^2-1 = \dfrac{1 xe^x}{1-e^x^2} \end{align*}
Thus,
\begin{align*} S &= \left( \dfrac{1}{1-x}^2 - 1 \right) \dfrac{1}{x(1-x)}. \\ &= \dfrac{1}{2-2x} - \dfrac{1}{x}. \\ &= \dfrac{2}{2(1-x)} - \dfrac{1}{x} \\ &= \dfrac{2 - 2x}{2x(1-x)}. \\ &= \dfrac{2}{2x} - \dfrac{2x}{2x(1-x)} \\ &= \dfrac{1}{x} - \dfrac{1}{1-x}. \\ &= \dfrac{1}{x} + \dfrac{1}{x} - \dfrac{2x}{1-(x)^2}. \\ &= \dfrac{}{ 1-${} $m$ r.} \\ \end{equation*}
